function compress(log) {
  const parts = [];
  let i = 0;
  while (i < log.length) {
    let run = 1;
    while (i + run < log.length && log[i + run] === log[i]) run++;
    parts.push(log[i] + run);
    i += run;
  }
  return parts.join("");
}
console.log(compress("AABBBCA"));

