function removeAt(items, index) {
  const removed = items[index];
  for (let i = index; i < items.length - 1; i++) {
    items[i] = items[i + 1];
  }
  items.length = items.length - 1;
  return removed;
}

const queue = ["Ada", "Bola", "Chidi", "Dayo"];
console.log(removeAt(queue, 1), queue.join(" "), queue.length);
